import {routePath,trackPath,watchPath} from './router.js';
import {esc,format,normalize,prepareImage} from './ui-utils.js';
import {mountVideoPlayer,secureUrl,youtubeId,readHistory} from './video-player.js';
import {authState} from './auth.js';
const $=id=>document.getElementById(id);
const reactions=[['like','👍','Gostei'],['heart','❤️','Amei'],['fire','🔥','Incrível'],['wow','😮','Surpreendente'],['clap','👏','Aplausos']];
export function initPlatform(host){
 let epoch=0,videos=[],player=null,watchItem=null,activeRoute='',videoDraft=null,busy=false,channelUID=null,socialState=null,videoFilter='all';
 const client=()=>host.state.client;
 const section=document.createElement('section');section.id='view-platform';section.className='view';section.hidden=true;document.querySelector('main footer').before(section);
 const nav=document.createElement('div');nav.innerHTML='<a class="nav-item" href="/videos" data-nav="videos"><svg class="icon" aria-hidden="true"><use href="#i-video"/></svg>Vídeos</a><a class="nav-item" href="/inscricoes" data-nav="inscricoes"><svg class="icon" aria-hidden="true"><use href="#i-users"/></svg>Inscrições</a><a class="nav-item" href="/biblioteca" data-nav="biblioteca"><svg class="icon" aria-hidden="true"><use href="#i-clock"/></svg>Continuar assistindo</a>';document.querySelector('.sidebar-divider').before(...nav.children);
 document.body.insertAdjacentHTML('beforeend',`<dialog id="video-editor" class="wide-dialog" aria-labelledby="video-editor-title"><button class="icon-button dialog-close" aria-label="Fechar">×</button><p class="eyebrow">KYROSHIX STUDIO</p><h2 id="video-editor-title">Publicar vídeo</h2><form id="video-form" class="form-fields"><label>Título<input id="video-title-input" required maxlength="120"></label><div class="form-pair"><label>Artista / criador<input id="video-artist-input" required maxlength="200"></label><label>Fonte<select id="video-source-input"><option value="upload">Enviar MP4 ou WebM</option><option value="mp4">Link MP4</option><option value="webm">Link WebM</option><option value="youtube">YouTube</option><option value="hls">Streaming HLS</option><option value="dash">Streaming DASH</option></select></label></div><label id="video-file-wrap">Vídeo <small>Até 50 MB. Para arquivos maiores, use uma URL de streaming.</small><input id="video-file-input" type="file" accept="video/mp4,video/webm"></label><label id="video-url-wrap" hidden>Endereço do vídeo<input id="video-url-input" type="url" placeholder="https://"></label><label>Descrição<textarea id="video-description-input" rows="4" maxlength="5000"></textarea></label><div class="form-pair"><label>Miniatura<input id="video-cover-input" type="file" accept="image/png,image/jpeg,image/webp"></label><label>Duração em segundos<input id="video-duration-input" type="number" min="0" max="7200" value="0" step="any"></label></div><label>Créditos<textarea id="video-credits-input" maxlength="2000" rows="2"></textarea></label><details class="advanced-options"><summary>Legendas, capítulos e proteção</summary><label>Legenda em WebVTT — URL HTTPS<input id="video-caption-input" type="url" placeholder="https://…/legenda.vtt"></label><label>Capítulos — um por linha: 0:00 Título<textarea id="video-chapters-input" rows="3" placeholder="0:00 Introdução&#10;0:30 Drop"></textarea></label><label>Proteção do streaming<select id="video-drm-input"><option value="none">Sem DRM</option><option value="widevine">Widevine — exige serviço de licenças</option><option value="playready">PlayReady — exige serviço de licenças</option><option value="fairplay">FairPlay — exige serviço de licenças</option></select></label><p class="subtle">DRM exige HLS/DASH já criptografado e um servidor de licenças configurado. Escolher essa opção não criptografa um MP4.</p></details><label class="checkbox"><input type="checkbox" id="video-published-input" checked> Publicar no catálogo</label><p class="subtle">Rascunhos ocultam o cadastro. Arquivos enviados ao armazenamento público continuam acessíveis pela URL.</p><p id="video-save-status" class="inline-message" role="status" hidden></p><progress id="video-progress" max="100" value="0" hidden></progress><div class="dialog-actions"><button class="primary" id="video-save">Salvar vídeo</button></div></form></dialog><dialog id="channel-editor" aria-labelledby="channel-editor-title"><button class="icon-button dialog-close" aria-label="Fechar">×</button><p class="eyebrow">SEU CANAL</p><h2 id="channel-editor-title">Um endereço só seu.</h2><form id="channel-form" class="form-fields"><label>Nome de usuário<input id="channel-handle" required pattern="[a-z0-9][a-z0-9_-]{2,29}" minlength="3" maxlength="30" placeholder="kyroshix"></label><p class="subtle">Seu link: #canal/seu-nome</p><label>Links — até 5, um por linha<textarea id="channel-links" rows="5" placeholder="YouTube | https://youtube.com/@…&#10;Instagram | https://instagram.com/…"></textarea></label><p id="channel-status" class="inline-message" role="status" hidden></p><button class="primary">Salvar canal</button></form></dialog>`);
 for(const id of ['video-editor','channel-editor']){$(id).querySelector('.dialog-close').onclick=()=>{if(!busy)$(id).close();};$(id).addEventListener('cancel',e=>{if(busy)e.preventDefault();});}
 $('video-source-input').onchange=sourceFields;
 function sourceFields(){const upload=$('video-source-input').value==='upload';$('video-file-wrap').hidden=!upload;$('video-url-wrap').hidden=upload;$('video-url-input').required=!upload;$('video-url-input').disabled=upload;}
 function unavailable(message='Esta área está em ativação. As músicas continuam disponíveis.'){section.innerHTML=`<div class="empty-state feature-empty"><span class="empty-orbit">◎</span><h1>Seu universo está crescendo.</h1><p>${esc(message)}</p><a class="primary" href="/musicas">Explorar músicas</a></div>`;}
 function cover(v){const url=host.media(v.cover_path);return url?`<img src="${esc(url)}" alt="" loading="lazy">`:`<span class="video-placeholder"><span class="brand-symbol"></span><span>KYROSHIX</span></span>`;}
 function card(v){return `<article class="video-card"><a class="video-thumbnail" href="${esc(watchPath(v))}">${cover(v)}<span class="play-bubble">▶</span><span class="duration-badge">${format(v.duration)}</span>${!v.published?'<span class="draft-badge">Rascunho</span>':''}</a><h3><a href="${esc(watchPath(v))}">${esc(v.title)}</a></h3><p>${esc(v.artists)}</p><small>${new Date(v.created_at).toLocaleDateString('pt-BR')} · ${v.video_source==='youtube'?'YouTube':'Vídeo'}</small></article>`;}
 function reactionHTML(data={}){return reactions.map(([key,emoji,label])=>`<button class="reaction ${data.mine?.includes(key)?'active':''}" data-reaction="${key}" aria-label="${label}" aria-pressed="${!!data.mine?.includes(key)}"><span>${emoji}</span><span>${key==='like'?'Gostei ':''}${Number(data.counts?.[key]||0)}</span></button>`).join('');}
 async function social(target,trackID,uid){try{const data=await client().rpc('social',{p_track:trackID,p_channel:uid});if(!target.isConnected)return;target.innerHTML=`<div class="reaction-bar">${reactionHTML(data)}</div>`;target.onclick=async e=>{const button=e.target.closest('[data-reaction]');if(!button||button.disabled||!host.requireUser())return;button.disabled=true;try{await client().rpc('react',{p_track:trackID,p_reaction:button.dataset.reaction,p_active:button.getAttribute('aria-pressed')!=='true'});await social(target,trackID,uid);}catch(e){host.toast(e.message);}finally{button.disabled=false;}};}catch{target.innerHTML='<p class="subtle">Reações estarão disponíveis após a ativação do upgrade.</p>';}}
 async function subscribeHTML(target,uid){if(!uid||!client())return;try{const data=await client().rpc('social',{p_channel:uid});if(!target.isConnected)return;target.innerHTML=`<span class="subtle">${data.subscribers} ${data.subscribers===1?'inscrito':'inscritos'}</span>${authState.user?.uid===uid?'':`<button class="${data.subscribed?'secondary':'primary'}" data-subscribe aria-pressed="${data.subscribed}">${data.subscribed?'Inscrito ✓':'Inscrever-se'}</button>`}`;target.querySelector('button')?.addEventListener('click',async e=>{if(!host.requireUser())return;const b=e.currentTarget;b.disabled=true;try{await client().rpc('subscribe',{p_channel:uid,p_active:!data.subscribed});await subscribeHTML(target,uid);}catch(error){host.toast(error.message);b.disabled=false;}});}catch{target.textContent='Inscrições em ativação.';}}
 async function listing(name,token){section.innerHTML='<p class="loading-line" role="status">Carregando vídeos…</p>';videos=await client().videos();if(token!==epoch)return;const history=readHistory();let rows=name==='biblioteca'?videos.filter(v=>history[v.id]?.time>0).sort((a,b)=>history[b.id].updated-history[a.id].updated):videos;
 const query=normalize(host.state.query);if(query)rows=rows.filter(v=>normalize(v.title+' '+v.artists).includes(query));if(videoFilter==='recent')rows=rows.slice().sort((a,b)=>b.created_at.localeCompare(a.created_at));
 section.innerHTML=`<div class="section-title"><div><p class="eyebrow">${name==='biblioteca'?'NO SEU TEMPO':'KYROSHIX WATCH'}</p><h1>${name==='biblioteca'?'De onde você parou.':'Dê play no seu universo.'}</h1></div>${host.state.owner?'<button class="primary" data-new-video>＋ Publicar vídeo</button>':''}</div><p class="subtle">${name==='biblioteca'?'Seu histórico fica apenas neste navegador.':'Música para ouvir. Histórias para assistir.'}</p><div class="platform-tabs"><a class="${name==='videos'?'active':''}" href="/videos">Todos os vídeos</a><a class="${name==='biblioteca'?'active':''}" href="/biblioteca">Continuar assistindo</a>${name==='biblioteca'?'<button data-clear-history>Limpar histórico</button>':''}</div><div class="video-grid">${rows.map(card).join('')}</div>${rows.length?'':`<div class="empty-state"><span class="empty-orbit">▷</span><h2>${query?'Nenhum resultado':'Seu próximo play começa aqui.'}</h2><p>${name==='biblioteca'?'Os vídeos que você começar a assistir aparecerão aqui.':'Os vídeos publicados pelo Estúdio aparecerão aqui.'}</p>${host.state.owner?'<button class="secondary" data-new-video>Adicionar primeiro vídeo</button>':''}</div>`}`;
 }
 async function watch(id,token){host.audio.pause();section.innerHTML='<p class="loading-line" role="status">Preparando seu próximo play…</p>';const v=await client().video(id);if(token!==epoch)return;if(!v){unavailable('Vídeo não encontrado ou ainda não publicado.');return;}
 watchItem=v;host.router.canonicalize(watchPath(v));const p=await client().profile(v.channel_uid).catch(()=>null);if(token!==epoch)return;
 section.innerHTML=`<a class="back-link" href="/videos">‹ Explorar vídeos</a><div class="watch-layout"><div class="watch-main"><div class="cinema-player" id="cinema-player" aria-label="Player de vídeo"></div><div class="watch-heading"><div><p class="eyebrow">${v.drm_system==='none'?'KYROSHIX WATCH':'STREAMING · '+v.drm_system.toUpperCase()}</p><h1>${esc(v.title)}</h1><p class="subtle">${esc(v.artists)}</p></div><button class="secondary" data-video-share="${esc(v.id)}">↗ Compartilhar</button></div><div class="channel-line"><a href="${esc(routePath(p?.handle?'canal':'perfil',p?.handle||v.channel_uid))}">${host.avatar(p||{display_name:v.artists})}<strong>${esc(p?.display_name||v.artists)}</strong></a><div id="watch-subscription" class="subscribe-area"></div></div><div id="video-reactions"></div><div class="detail-description"><p>${esc(v.description)}</p><details><summary>Créditos</summary><p>${esc(v.credits||'Créditos não informados.')}</p></details></div>${v.chapters?.length?`<section class="chapters"><h2>Capítulos</h2>${v.chapters.map(c=>`<button data-chapter="${Number(c.start)}"><span>${format(c.start)}</span>${esc(c.title)}</button>`).join('')}</section>`:''}<div id="video-discussion"></div></div><aside class="watch-next"><h2>Próximos vídeos</h2><div id="next-videos"></div></aside></div>`;
 const discussion=document.querySelector('.comments-section');$('video-discussion').append(discussion);host.comments(v.id);social($('video-reactions'),v.id,v.channel_uid);subscribeHTML($('watch-subscription'),v.channel_uid);
 const mounting=mountVideoPlayer($('cinema-player'),v,{media:host.media,onPlay:()=>host.audio.pause(),toast:host.toast,getToken:()=>authState.client?.token?.()||Promise.resolve(null)});
 client().videos().then(list=>{if(token===epoch)$('next-videos').innerHTML=list.filter(x=>x.id!==id).slice(0,5).map(card).join('')||'<p class="subtle">Novos vídeos aparecem aqui.</p>';}).catch(()=>{});
 const mounted=await mounting;if(token!==epoch)mounted.destroy();else player=mounted;
 }
 async function channel(handle,token){section.innerHTML='<p class="loading-line">Carregando canal…</p>';const p=await client().profileByHandle(handle);if(token!==epoch)return;if(!p){unavailable('Este canal ainda não foi criado.');return;}channelUID=p.uid;const rows=await client().channelTracks(p.uid);if(token!==epoch)return;const banner=host.media(p.banner_path,p.updated_at);
 section.innerHTML=`<div class="channel-hero" ${banner?`style="background-image:url('${esc(banner)}')"`:''}></div><div class="channel-title">${host.avatar(p,'channel-avatar')}<div><p class="eyebrow">@${esc(p.handle)}</p><h1>${esc(p.display_name)}</h1><p>${esc(p.bio)}</p></div><div id="channel-subscription" class="subscribe-area"></div></div><div class="channel-links">${(p.links||[]).filter(l=>secureUrl(l.url)).map(l=>`<a class="secondary" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a>`).join('')}${authState.user?.uid===p.uid?'<button class="secondary" data-channel-edit>Editar canal</button>':''}<button class="text-button" data-channel-share>Copiar link</button></div><div class="platform-tabs"><a href="${esc(routePath('canal',p.handle))}" class="active">Lançamentos</a><a href="${esc(routePath('perfil',p.uid))}">Sobre o criador</a></div><div class="video-grid">${rows.map(t=>t.kind==='video'?card(t):`<article class="video-card"><a class="video-thumbnail" href="${esc(trackPath(t))}">${host.cover(t)}</a><h3><a href="${esc(trackPath(t))}">${esc(t.title)}</a></h3><p>${esc(t.artists)}</p><small>Faixa · ${format(t.duration)}</small></article>`).join('')}</div>${rows.length?'':'<p class="empty-state">Os lançamentos desse canal aparecerão aqui.</p>'}`;subscribeHTML($('channel-subscription'),p.uid);
 }
 async function subscriptions(token){if(!host.requireUser()){unavailable('Entre para acompanhar suas inscrições.');return;}const rows=await client().rpc('my_subscriptions');if(token!==epoch)return;section.innerHTML=`<div class="section-title"><div><p class="eyebrow">MAIS PERTO DE QUEM CRIA</p><h1>Suas inscrições.</h1></div></div><div class="subscription-grid">${rows.map(p=>`<a class="subscription-card" href="${esc(routePath(p.handle?'canal':'perfil',p.handle||p.uid))}">${host.avatar(p,'channel-avatar')}<h2>${esc(p.display_name)}</h2><p>${esc(p.status||p.bio)}</p><span>Abrir canal ↗</span></a>`).join('')}</div>${rows.length?'':'<div class="empty-state"><h2>Uma nova conexão começa com um play.</h2><p>Inscreva-se em um perfil ou canal para encontrá-lo aqui.</p><a class="secondary" href="/musicas">Descobrir músicas</a></div>'}`;}
 function leave(){++epoch;player?.destroy();player=null;watchItem=null;document.body.classList.remove('video-route');const discussion=document.querySelector('.comments-section');if(discussion&&!document.querySelector('.track-main').contains(discussion))document.querySelector('.track-main').append(discussion);section.hidden=true;activeRoute='';}
 async function show(name,arg){const token=++epoch;activeRoute=name;section.hidden=false;document.body.classList.toggle('video-route',name==='assistir');if(!client()){unavailable();return;}try{if(name==='assistir')await watch(arg,token);else if(name==='canal')await channel(arg,token);else if(name==='inscricoes')await subscriptions(token);else await listing(name,token);}catch{if(token===epoch)unavailable('Esta área precisa da atualização do banco. Se ela já foi ativada, confira sua conexão e tente novamente.');}}
 async function openVideo(id){if(!host.state.owner){host.toast('O Estúdio é exclusivo da conta dona.');return;}try{videoDraft=id?await client().video(id):{id:crypto.randomUUID(),title:'',artists:authState.user?.displayName||'KYROSHIX',description:'',credits:'',video_source:'mp4',video_url:'',cover_path:'',duration:0,chapters:[],caption_url:'',drm_system:'none',published:true,byte_size:0};if(!videoDraft)throw Error('Vídeo não encontrado.');$('video-form').reset();for(const [input,key]of Object.entries({'video-title-input':'title','video-artist-input':'artists','video-description-input':'description','video-credits-input':'credits','video-duration-input':'duration','video-caption-input':'caption_url','video-drm-input':'drm_system'}))$(input).value=videoDraft[key]||'';$('video-source-input').value=!videoDraft.video_url||videoDraft.video_url.startsWith('videos/')?'upload':videoDraft.video_source;$('video-url-input').value=videoDraft.video_source==='youtube'?'https://youtube.com/watch?v='+videoDraft.video_url:videoDraft.video_url;$('video-published-input').checked=videoDraft.published;$('video-chapters-input').value=(videoDraft.chapters||[]).map(c=>`${format(c.start)} ${c.title}`).join('\n');$('video-editor-title').textContent=id?'Editar vídeo':'Publicar vídeo';host.message('video-save-status');sourceFields();$('video-editor').showModal();}catch(e){host.toast(e.message);}}
 async function videoDuration(file){if(!['video/mp4','video/webm'].includes(file.type)||file.size>50*1024*1024||file.size<64)throw Error('Escolha um vídeo MP4 ou WebM de até 50 MB.');const url=URL.createObjectURL(file);try{return await new Promise((resolve,reject)=>{const v=document.createElement('video'),timeout=setTimeout(()=>{v.removeAttribute('src');reject(Error('Não foi possível ler o vídeo. Confira o formato.'));},15000);v.preload='metadata';v.onloadedmetadata=()=>{clearTimeout(timeout);const d=v.duration;v.removeAttribute('src');if(!Number.isFinite(d)||d<=0||d>7200)reject(Error('Escolha um vídeo de até duas horas.'));else resolve(d);};v.onerror=()=>{clearTimeout(timeout);reject(Error('Esse vídeo não pôde ser lido pelo navegador.'));};v.src=url;});}finally{URL.revokeObjectURL(url);}}
 $('video-form').onsubmit=async e=>{e.preventDefault();if(busy||!host.state.owner)return;busy=true;host.modalBusy($('video-editor'),true);const uploaded=[];let committed=false;try{const next={...videoDraft,title:$('video-title-input').value.trim(),artists:$('video-artist-input').value.trim(),description:$('video-description-input').value,credits:$('video-credits-input').value,caption_url:$('video-caption-input').value.trim(),duration:Number($('video-duration-input').value)||0,drm_system:$('video-drm-input').value,published:$('video-published-input').checked};next.chapters=$('video-chapters-input').value.split('\n').filter(x=>x.trim()).map(line=>{const m=line.trim().match(/^(\d+):(\d{2})\s+(.+)$/);if(!m||Number(m[2])>59)throw Error('Use 0:00 Título em cada capítulo.');return{start:Number(m[1])*60+Number(m[2]),title:m[3]};});const src=$('video-source-input').value;const progress=p=>{$('video-progress').hidden=false;$('video-progress').value=p;};if(src==='upload'){const f=$('video-file-input').files[0];if(f){host.message('video-save-status','Preparando o vídeo…');next.duration=await videoDuration(f);next.byte_size=f.size;next.video_source=f.type==='video/mp4'?'mp4':'webm';next.video_url=`videos/${next.id}/${crypto.randomUUID()}.${next.video_source}`;host.message('video-save-status','Enviando vídeo… Mantenha a página aberta.');await client().upload(next.video_url,f,progress);uploaded.push(next.video_url);}else if(!next.video_url?.startsWith('videos/'))throw Error('Escolha o arquivo de vídeo.');}else{next.video_source=src;next.video_url=src==='youtube'?youtubeId($('video-url-input').value):secureUrl($('video-url-input').value);if(!next.video_url)throw Error('Confira o endereço do vídeo.');}if(next.drm_system!=='none'&&!['hls','dash'].includes(next.video_source))throw Error('DRM exige uma fonte HLS ou DASH criptografada.');const img=$('video-cover-input').files[0];if(img){host.message('video-save-status','Enviando miniatura…');next.cover_path=`tracks/${next.id}/${crypto.randomUUID()}.webp`;await client().upload(next.cover_path,await prepareImage(img,2560,1440),progress);uploaded.push(next.cover_path);}host.message('video-save-status','Salvando o vídeo…');await client().rpc('save_video',{p_video:next});committed=true;const stale=[videoDraft.video_url,videoDraft.cover_path].filter(p=>p&&p!==next.video_url&&p!==next.cover_path);$('video-editor').close();host.toast(next.published?'Vídeo publicado.':'Rascunho salvo.');if(stale.length)client().removeFiles(stale).catch(()=>host.toast('Vídeo salvo. Um arquivo antigo ainda precisa ser removido.'));if(host.state.view==='studio')studio();else if(host.state.view==='videos')show('videos');else host.router.navigate('videos');}catch(error){host.message('video-save-status',error.message,'error');if(!committed&&uploaded.length)await client().removeFiles(uploaded).catch(()=>{});}finally{busy=false;host.modalBusy($('video-editor'),false);sourceFields();$('video-progress').hidden=true;}};
 async function editChannel(){if(!host.requireUser())return;try{if(!host.state.profile)host.state.profile=await client().rpc('save_profile',{p_profile:{display_name:authState.user.displayName||'Criador'}});const p=host.state.profile;$('channel-handle').value=p.handle||'';$('channel-links').value=(p.links||[]).map(l=>l.label+' | '+l.url).join('\n');host.message('channel-status');$('channel-editor').showModal();}catch(e){host.toast(e.message);}}
 $('channel-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;host.modalBusy($('channel-editor'),true);try{const links=$('channel-links').value.split('\n').filter(x=>x.trim()).map(x=>{const i=x.indexOf('|');const label=x.slice(0,i).trim(),url=secureUrl(x.slice(i+1).trim());if(i<1||!url)throw Error('Use Nome | https://endereço em cada link.');return{label,url};});host.state.profile=await client().rpc('save_channel',{p_handle:$('channel-handle').value.trim().toLowerCase(),p_links:links});$('channel-editor').close();host.router.navigate('canal',host.state.profile.handle);}catch(e){host.message('channel-status',e.message,'error');}finally{busy=false;host.modalBusy($('channel-editor'),false);}};
 async function studio(){let target=$('studio-videos');if(!target){target=document.createElement('section');target.id='studio-videos';$('studio-content').append(target);}if(!host.state.owner)return;target.innerHTML='<p class="subtle">Carregando vídeos…</p>';try{const rows=await client().videos(true);if(!host.state.owner){target.innerHTML='';return;}target.innerHTML=`<div class="section-title"><div><p class="eyebrow">VÍDEOS</p><h2>Seu próximo capítulo.</h2></div><button class="primary" data-new-video>＋ Publicar vídeo</button></div>${rows.map(v=>`<div class="studio-row"><span class="studio-video-cover">${cover(v)}</span><div class="studio-row-text"><strong>${esc(v.title)}</strong><small>${v.published?'Publicado':'Rascunho'} · ${esc(v.video_source.toUpperCase())}</small></div><div class="studio-row-actions"><button class="secondary" data-edit-video="${esc(v.id)}">Editar</button><button class="text-button" data-delete-video="${esc(v.id)}">Excluir</button></div></div>`).join('')||'<p class="subtle">Publique seu primeiro vídeo por arquivo ou URL.</p>'}`;}catch{target.innerHTML='<p class="inline-message">O Estúdio de vídeos será liberado após a instalação das migrações do upgrade.</p>';}}
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-new-video'))openVideo();if(b.dataset.editVideo)openVideo(b.dataset.editVideo);if(b.dataset.deleteVideo){const v=await client().video(b.dataset.deleteVideo);if(v&&await host.confirmAction('Excluir vídeo?',`“${v.title}” e seus comentários serão excluídos.`)){await client().rpc('delete_track',{p_id:v.id});await client().removeFiles([v.video_url,v.cover_path]);studio();}}if(b.dataset.chapter)player?.seek(Number(b.dataset.chapter));if(b.hasAttribute('data-channel-edit'))editChannel();if(b.dataset.videoShare||b.hasAttribute('data-channel-share')){const url=new URL(b.dataset.videoShare?watchPath(watchItem||{id:b.dataset.videoShare}):location.pathname,location.origin).href;if(navigator.share)await navigator.share({title:document.title,url});else{await navigator.clipboard.writeText(url);host.toast('Link copiado.');}}if(b.hasAttribute('data-clear-history')){localStorage.removeItem('krs-watch-history');show('biblioteca');}}catch(error){if(error.name!=='AbortError')host.toast(error.message);}});
 host.audio.addEventListener('play',()=>player?.pause());
 return {
  route(name,arg){leave();if(!['videos','assistir','canal','inscricoes','biblioteca'].includes(name))return false;host.state.view=name;show(name,arg);return true;},
  search(){if(['videos','biblioteca'].includes(activeRoute)){show(activeRoute);return true;}return false;},
  studio,
  track(t){const target=document.createElement('div');target.className='social-section';$('track-detail').querySelector('.detail-actions').after(target);if(client())social(target,t.id,t.channel_uid);},
  profile(uid,p){const box=document.createElement('div');box.className='channel-profile-tools';const own=authState.user?.uid===uid;box.innerHTML=`<div class="subscribe-area"></div><div class="channel-links">${p?.handle?`<a class="primary" href="${esc(routePath('canal',p.handle))}">Abrir canal ↗</a>`:''}${own?'<button class="secondary" data-channel-edit>Personalizar canal e links</button>':''}</div>`;$('public-profile').append(box);subscribeHTML(box.querySelector('.subscribe-area'),uid);},
  refresh(){if(activeRoute==='assistir'&&watchItem&&$('video-reactions')){social($('video-reactions'),watchItem.id,watchItem.channel_uid);subscribeHTML($('watch-subscription'),watchItem.channel_uid);}if(activeRoute==='canal'&&channelUID&&$('channel-subscription'))subscribeHTML($('channel-subscription'),channelUID);if(host.state.view==='faixa'&&host.state.commentTrack){const target=document.querySelector('.social-section');if(target)social(target,host.state.commentTrack,null);}if(activeRoute==='inscricoes')show('inscricoes');if(host.state.view==='studio')studio();},
 };
}
